package protocol7::module::coding::helper::enforce_quota;

use strict;
use warnings;
use protocol7::module::base qw( log_warn );
use protocol7::config qw( read_config );

##
## Reads the per-job byte quota from the config.
##
## @return the quota limit, or 4096 if not found in config
##
sub read_config
{
    my $key = 'max_job_bytes';
    my $cfg = read_config();
    return $cfg->{$key} || 4096;
}

##
## Checks if the job is within its byte quota.
##
## @param $job_id  the job identifier
## @param $bytes  the number of bytes used by the job
##
## @return TRUE if within quota, FALSE if exceeded
##
sub check
{
    my ( $job_id, $bytes ) = @_;

    my $limit = read_config();

    if ( $bytes > $limit )
    {
        log_warn(
            'Job [%s] exceeded byte quota: %d bytes used, limit is %d',
            $job_id,
            $bytes,
            $limit,
        );
        return FALSE;
    }

    return TRUE;
}

##
## Enforces the per-job byte quota.
##
## This is the exported public function.
##
## @param $job_id  the job identifier
## @param $bytes  the number of bytes used by the job
##
## @return TRUE if the job is within quota, FALSE if exceeded
##
sub enforce_quota
{
    my ( $job_id, $bytes ) = @_;

    return check( $job_id, $bytes );
}

1;

__PACKAGE__->import( qw( read_config check ) );
```

## Design Notes

| Aspect | Choice |
|--------|--------|
| **Default quota** | `4096` (4KB) as specified |
| **Config key** | `max_job_bytes` |
| **Return value** | `TRUE` if within quota, `FALSE` if exceeded |
| **Logging** | Uses the existing `protocol7::module::base::log_warn` |

